-- D1 content model and actor-wide command namespace; additive to 0001-0003.
PRAGMA foreign_keys=ON;
CREATE TABLE projects(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL REFERENCES workspaces(id),name TEXT NOT NULL CHECK(length(name) BETWEEN 1 AND 160),status TEXT NOT NULL DEFAULT 'draft' CHECK(status IN('draft','uploading','selecting','submitted','retouching','reviewing','approved','delivered','archived')),versioning_mode TEXT NOT NULL DEFAULT 'manual' CHECK(versioning_mode IN('off','manual','auto_filename','assisted')),revision INTEGER NOT NULL DEFAULT 1 CHECK(revision>0),archived_from_status TEXT CHECK(archived_from_status IN('draft','delivered')),created_at TEXT NOT NULL DEFAULT(strftime('%Y-%m-%dT%H:%M:%fZ','now')),UNIQUE(id,workspace_id),CHECK(status='archived' OR archived_from_status IS NULL));
CREATE INDEX projects_workspace_page ON projects(workspace_id,created_at DESC,id DESC);
CREATE TABLE albums(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL,project_id TEXT NOT NULL,name TEXT NOT NULL CHECK(length(name) BETWEEN 1 AND 160),state TEXT NOT NULL DEFAULT 'draft' CHECK(state IN('draft','active','archived','deleting','deleted')),is_pinned INTEGER NOT NULL DEFAULT 0 CHECK(is_pinned IN(0,1)),legal_hold INTEGER NOT NULL DEFAULT 0 CHECK(legal_hold IN(0,1)),revision INTEGER NOT NULL DEFAULT 1 CHECK(revision>0),archived_from_state TEXT CHECK(archived_from_state='draft'),created_at TEXT NOT NULL DEFAULT(strftime('%Y-%m-%dT%H:%M:%fZ','now')),UNIQUE(id,workspace_id),FOREIGN KEY(project_id,workspace_id) REFERENCES projects(id,workspace_id),CHECK(state='archived' OR archived_from_state IS NULL));
CREATE INDEX albums_workspace_project_page ON albums(workspace_id,project_id,created_at DESC,id DESC);
CREATE TABLE photos(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL,project_id TEXT NOT NULL,album_id TEXT NOT NULL,original_filename TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT(strftime('%Y-%m-%dT%H:%M:%fZ','now')),FOREIGN KEY(project_id,workspace_id) REFERENCES projects(id,workspace_id),FOREIGN KEY(album_id,workspace_id) REFERENCES albums(id,workspace_id));
CREATE INDEX photos_album_content ON photos(workspace_id,project_id,album_id);
CREATE TABLE request_commands(actor_id TEXT NOT NULL REFERENCES users(id),request_id TEXT NOT NULL,operation TEXT NOT NULL CHECK(operation IN('workspace.created','project.created','project.renamed','project.archived','project.restored','album.created','album.renamed','album.protection_changed','album.archived','album.restored')),payload_json TEXT NOT NULL,session_id TEXT NOT NULL,workspace_id TEXT,resource_id TEXT NOT NULL,before_json TEXT,result_json TEXT,created_at TEXT NOT NULL DEFAULT(strftime('%Y-%m-%dT%H:%M:%fZ','now')),PRIMARY KEY(actor_id,request_id));
INSERT INTO request_commands(actor_id,request_id,operation,payload_json,session_id,workspace_id,resource_id,result_json,created_at) SELECT c.actor_id,c.request_id,'workspace.created',json_object('name',c.name),c.session_id,(SELECT w.id FROM workspaces w WHERE w.id=c.workspace_id),c.workspace_id,c.result_json,(SELECT w.created_at FROM workspaces w WHERE w.id=c.workspace_id) FROM workspace_commands c;
CREATE TRIGGER request_command_guard BEFORE INSERT ON request_commands BEGIN SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM owners o JOIN owner_sessions s ON s.userId=o.user_id WHERE o.user_id=NEW.actor_id AND o.enabled=1 AND s.id=NEW.session_id AND s.expiresAt>unixepoch('subsec')*1000) THEN RAISE(ABORT,'OWNER_REQUIRED') END; SELECT CASE WHEN EXISTS(SELECT 1 FROM request_commands c WHERE c.actor_id=NEW.actor_id AND c.request_id=NEW.request_id AND (c.operation<>NEW.operation OR c.payload_json<>NEW.payload_json)) THEN RAISE(ABORT,'REQUEST_ID_CONFLICT') END; SELECT CASE WHEN EXISTS(SELECT 1 FROM request_commands c WHERE c.actor_id=NEW.actor_id AND c.request_id=NEW.request_id) THEN RAISE(IGNORE) END; SELECT CASE WHEN NEW.operation='workspace.created' AND (SELECT count(*) FROM workspaces WHERE owner_user_id=NEW.actor_id)>=100 THEN RAISE(ABORT,'WORKSPACE_LIMIT_REACHED') END; SELECT CASE WHEN NEW.operation='project.created' AND NOT EXISTS(SELECT 1 FROM workspaces w WHERE w.id=json_extract(NEW.payload_json,'$.workspaceId') AND w.owner_user_id=NEW.actor_id) THEN RAISE(ABORT,'NOT_FOUND') END; SELECT CASE WHEN NEW.operation='album.created' AND NOT EXISTS(SELECT 1 FROM projects p JOIN workspaces w ON w.id=p.workspace_id WHERE p.id=json_extract(NEW.payload_json,'$.projectId') AND w.owner_user_id=NEW.actor_id AND p.status<>'archived') THEN RAISE(ABORT,'NOT_FOUND') END; SELECT CASE WHEN NEW.operation IN('project.renamed','project.archived','project.restored') AND NOT EXISTS(SELECT 1 FROM projects p JOIN workspaces w ON w.id=p.workspace_id WHERE p.id=NEW.resource_id AND w.owner_user_id=NEW.actor_id) THEN RAISE(ABORT,'NOT_FOUND') END; SELECT CASE WHEN NEW.operation IN('album.renamed','album.protection_changed','album.archived','album.restored') AND NOT EXISTS(SELECT 1 FROM albums a JOIN workspaces w ON w.id=a.workspace_id WHERE a.id=NEW.resource_id AND w.owner_user_id=NEW.actor_id) THEN RAISE(ABORT,'NOT_FOUND') END; SELECT CASE WHEN NEW.operation='project.renamed' AND NOT EXISTS(SELECT 1 FROM projects WHERE id=NEW.resource_id AND revision=json_extract(NEW.payload_json,'$.expectedRevision') AND status<>'archived') THEN RAISE(ABORT,CASE WHEN EXISTS(SELECT 1 FROM projects WHERE id=NEW.resource_id AND status='archived') THEN 'RESOURCE_NOT_EDITABLE' ELSE 'CONCURRENT_MODIFICATION' END) END; SELECT CASE WHEN NEW.operation='album.renamed' AND NOT EXISTS(SELECT 1 FROM albums a JOIN projects p ON p.id=a.project_id AND p.workspace_id=a.workspace_id WHERE a.id=NEW.resource_id AND a.revision=json_extract(NEW.payload_json,'$.expectedRevision') AND a.state NOT IN('archived','deleting','deleted') AND p.status<>'archived') THEN RAISE(ABORT,CASE WHEN EXISTS(SELECT 1 FROM albums a JOIN projects p ON p.id=a.project_id AND p.workspace_id=a.workspace_id WHERE a.id=NEW.resource_id AND (a.state IN('archived','deleting','deleted') OR p.status='archived')) THEN 'RESOURCE_NOT_EDITABLE' ELSE 'CONCURRENT_MODIFICATION' END) END; SELECT CASE WHEN NEW.operation='album.protection_changed' AND NOT EXISTS(SELECT 1 FROM albums WHERE id=NEW.resource_id AND revision=json_extract(NEW.payload_json,'$.expectedRevision') AND state NOT IN('deleting','deleted')) THEN RAISE(ABORT,CASE WHEN EXISTS(SELECT 1 FROM albums WHERE id=NEW.resource_id AND state IN('deleting','deleted')) THEN 'RESOURCE_NOT_EDITABLE' ELSE 'CONCURRENT_MODIFICATION' END) END; SELECT CASE WHEN NEW.operation='album.protection_changed' AND EXISTS(SELECT 1 FROM albums a WHERE a.id=NEW.resource_id AND ((a.is_pinned=1 AND json_extract(NEW.payload_json,'$.isPinned')=0) OR (a.legal_hold=1 AND json_extract(NEW.payload_json,'$.legalHold')=0)) AND json_extract(NEW.payload_json,'$.confirmUnprotect')<>1) THEN RAISE(ABORT,'PROTECTION_CONFIRMATION_REQUIRED') END; SELECT CASE WHEN NEW.operation IN('project.archived','project.restored') AND NOT EXISTS(SELECT 1 FROM projects WHERE id=NEW.resource_id AND revision=json_extract(NEW.payload_json,'$.expectedRevision')) THEN RAISE(ABORT,'CONCURRENT_MODIFICATION') END; SELECT CASE WHEN NEW.operation='project.archived' AND NOT EXISTS(SELECT 1 FROM projects WHERE id=NEW.resource_id AND status IN('draft','delivered') AND NOT EXISTS(SELECT 1 FROM albums WHERE project_id=projects.id) AND NOT EXISTS(SELECT 1 FROM photos p WHERE p.project_id=projects.id)) THEN RAISE(ABORT,CASE WHEN EXISTS(SELECT 1 FROM projects WHERE id=NEW.resource_id AND status NOT IN('draft','delivered')) THEN 'INVALID_STATE_TRANSITION' ELSE 'CONTENT_NOT_EMPTY_OR_IDLE' END) END; SELECT CASE WHEN NEW.operation='project.restored' AND NOT EXISTS(SELECT 1 FROM projects WHERE id=NEW.resource_id AND status='archived' AND archived_from_status IS NOT NULL) THEN RAISE(ABORT,'INVALID_STATE_TRANSITION') END; SELECT CASE WHEN NEW.operation IN('album.archived','album.restored') AND NOT EXISTS(SELECT 1 FROM albums a JOIN projects p ON p.id=a.project_id AND p.workspace_id=a.workspace_id WHERE a.id=NEW.resource_id AND a.revision=json_extract(NEW.payload_json,'$.expectedRevision') AND p.status<>'archived') THEN RAISE(ABORT,'CONCURRENT_MODIFICATION') END; SELECT CASE WHEN NEW.operation='album.archived' AND NOT EXISTS(SELECT 1 FROM albums WHERE id=NEW.resource_id AND state='draft') THEN RAISE(ABORT,'INVALID_STATE_TRANSITION') END; SELECT CASE WHEN NEW.operation='album.archived' AND (EXISTS(SELECT 1 FROM photos p WHERE p.album_id=NEW.resource_id) OR NOT EXISTS(SELECT 1 FROM albums a JOIN projects p ON p.id=a.project_id WHERE a.id=NEW.resource_id AND p.status IN('draft','delivered'))) THEN RAISE(ABORT,'CONTENT_NOT_EMPTY_OR_IDLE') END; SELECT CASE WHEN NEW.operation='album.restored' AND NOT EXISTS(SELECT 1 FROM albums WHERE id=NEW.resource_id AND state='archived' AND archived_from_state='draft') THEN RAISE(ABORT,'INVALID_STATE_TRANSITION') END; END;
CREATE TRIGGER request_workspace_apply AFTER INSERT ON request_commands WHEN NEW.operation='workspace.created' BEGIN INSERT INTO workspace_commands(actor_id,request_id,session_id,name,workspace_id) VALUES(NEW.actor_id,NEW.request_id,NEW.session_id,json_extract(NEW.payload_json,'$.name'),NEW.resource_id); UPDATE request_commands SET workspace_id=(SELECT workspace_id FROM workspace_commands WHERE actor_id=NEW.actor_id AND request_id=NEW.request_id),result_json=(SELECT result_json FROM workspace_commands WHERE actor_id=NEW.actor_id AND request_id=NEW.request_id) WHERE actor_id=NEW.actor_id AND request_id=NEW.request_id; END;
CREATE TRIGGER request_project_create AFTER INSERT ON request_commands WHEN NEW.operation='project.created' BEGIN INSERT INTO projects(id,workspace_id,name) VALUES(NEW.resource_id,json_extract(NEW.payload_json,'$.workspaceId'),json_extract(NEW.payload_json,'$.name')); UPDATE request_commands SET workspace_id=(SELECT workspace_id FROM projects WHERE id=NEW.resource_id),result_json=(SELECT json_object('id',id,'workspaceId',workspace_id,'name',name,'status',status,'versioningMode',versioning_mode,'revision',revision,'createdAt',created_at) FROM projects WHERE id=NEW.resource_id) WHERE actor_id=NEW.actor_id AND request_id=NEW.request_id; INSERT INTO audit_events(event_id,actor_type,actor_id,session_id,workspace_id,project_id,action,after_json,request_id) SELECT 'project:'||resource_id,'user',actor_id,session_id,workspace_id,resource_id,operation,result_json,request_id FROM request_commands WHERE actor_id=NEW.actor_id AND request_id=NEW.request_id; END;
CREATE TRIGGER request_album_create AFTER INSERT ON request_commands WHEN NEW.operation='album.created' BEGIN INSERT INTO albums(id,workspace_id,project_id,name) SELECT NEW.resource_id,p.workspace_id,p.id,json_extract(NEW.payload_json,'$.name') FROM projects p WHERE p.id=json_extract(NEW.payload_json,'$.projectId'); UPDATE request_commands SET workspace_id=(SELECT workspace_id FROM albums WHERE id=NEW.resource_id),result_json=(SELECT json_object('id',a.id,'workspaceId',a.workspace_id,'projectId',a.project_id,'name',a.name,'state',a.state,'isPinned',json(CASE WHEN a.is_pinned=1 THEN 'true' ELSE 'false' END),'legalHold',json(CASE WHEN a.legal_hold=1 THEN 'true' ELSE 'false' END),'revision',a.revision,'createdAt',a.created_at) FROM albums a WHERE a.id=NEW.resource_id) WHERE actor_id=NEW.actor_id AND request_id=NEW.request_id; INSERT INTO audit_events(event_id,actor_type,actor_id,session_id,workspace_id,project_id,album_id,action,after_json,request_id) SELECT 'album:'||resource_id,'user',actor_id,session_id,workspace_id,(SELECT project_id FROM albums WHERE id=resource_id),resource_id,operation,result_json,request_id FROM request_commands WHERE actor_id=NEW.actor_id AND request_id=NEW.request_id; END;
CREATE TRIGGER request_project_rename AFTER INSERT ON request_commands WHEN NEW.operation='project.renamed' BEGIN UPDATE request_commands SET workspace_id=(SELECT workspace_id FROM projects WHERE id=NEW.resource_id),before_json=(SELECT json_object('id',id,'workspaceId',workspace_id,'name',name,'status',status,'versioningMode',versioning_mode,'revision',revision,'createdAt',created_at) FROM projects WHERE id=NEW.resource_id) WHERE actor_id=NEW.actor_id AND request_id=NEW.request_id; UPDATE projects SET name=json_extract(NEW.payload_json,'$.name'),revision=revision+1 WHERE id=NEW.resource_id; UPDATE request_commands SET result_json=(SELECT json_object('id',id,'workspaceId',workspace_id,'name',name,'status',status,'versioningMode',versioning_mode,'revision',revision,'createdAt',created_at) FROM projects WHERE id=NEW.resource_id) WHERE actor_id=NEW.actor_id AND request_id=NEW.request_id; INSERT INTO audit_events(event_id,actor_type,actor_id,session_id,workspace_id,project_id,action,before_json,after_json,request_id) SELECT 'project:'||resource_id||':'||request_id,'user',actor_id,session_id,workspace_id,resource_id,operation,before_json,result_json,request_id FROM request_commands WHERE actor_id=NEW.actor_id AND request_id=NEW.request_id; END;
CREATE TRIGGER request_album_rename AFTER INSERT ON request_commands WHEN NEW.operation='album.renamed' BEGIN UPDATE request_commands SET workspace_id=(SELECT workspace_id FROM albums WHERE id=NEW.resource_id),before_json=(SELECT json_object('id',id,'workspaceId',workspace_id,'projectId',project_id,'name',name,'state',state,'isPinned',json(CASE WHEN is_pinned=1 THEN 'true' ELSE 'false' END),'legalHold',json(CASE WHEN legal_hold=1 THEN 'true' ELSE 'false' END),'revision',revision,'createdAt',created_at) FROM albums WHERE id=NEW.resource_id) WHERE actor_id=NEW.actor_id AND request_id=NEW.request_id; UPDATE albums SET name=json_extract(NEW.payload_json,'$.name'),revision=revision+1 WHERE id=NEW.resource_id; UPDATE request_commands SET result_json=(SELECT json_object('id',a.id,'workspaceId',a.workspace_id,'projectId',a.project_id,'name',a.name,'state',a.state,'isPinned',json(CASE WHEN a.is_pinned=1 THEN 'true' ELSE 'false' END),'legalHold',json(CASE WHEN a.legal_hold=1 THEN 'true' ELSE 'false' END),'revision',a.revision,'createdAt',a.created_at) FROM albums a WHERE a.id=NEW.resource_id) WHERE actor_id=NEW.actor_id AND request_id=NEW.request_id; INSERT INTO audit_events(event_id,actor_type,actor_id,session_id,workspace_id,project_id,album_id,action,before_json,after_json,request_id) SELECT 'album:'||resource_id||':'||request_id,'user',actor_id,session_id,workspace_id,(SELECT project_id FROM albums WHERE id=resource_id),resource_id,operation,before_json,result_json,request_id FROM request_commands WHERE actor_id=NEW.actor_id AND request_id=NEW.request_id; END;
CREATE TRIGGER request_album_protection AFTER INSERT ON request_commands WHEN NEW.operation='album.protection_changed' BEGIN UPDATE request_commands SET workspace_id=(SELECT workspace_id FROM albums WHERE id=NEW.resource_id),before_json=(SELECT json_object('id',id,'workspaceId',workspace_id,'projectId',project_id,'name',name,'state',state,'isPinned',json(CASE WHEN is_pinned=1 THEN 'true' ELSE 'false' END),'legalHold',json(CASE WHEN legal_hold=1 THEN 'true' ELSE 'false' END),'revision',revision,'createdAt',created_at) FROM albums WHERE id=NEW.resource_id) WHERE actor_id=NEW.actor_id AND request_id=NEW.request_id; UPDATE albums SET is_pinned=json_extract(NEW.payload_json,'$.isPinned'),legal_hold=json_extract(NEW.payload_json,'$.legalHold'),revision=revision+1 WHERE id=NEW.resource_id; UPDATE request_commands SET result_json=(SELECT json_object('id',a.id,'workspaceId',a.workspace_id,'projectId',a.project_id,'name',a.name,'state',a.state,'isPinned',json(CASE WHEN a.is_pinned=1 THEN 'true' ELSE 'false' END),'legalHold',json(CASE WHEN a.legal_hold=1 THEN 'true' ELSE 'false' END),'revision',a.revision,'createdAt',a.created_at) FROM albums a WHERE a.id=NEW.resource_id) WHERE actor_id=NEW.actor_id AND request_id=NEW.request_id; INSERT INTO audit_events(event_id,actor_type,actor_id,session_id,workspace_id,project_id,album_id,action,before_json,after_json,request_id) SELECT 'album:'||resource_id||':'||request_id,'user',actor_id,session_id,workspace_id,(SELECT project_id FROM albums WHERE id=resource_id),resource_id,operation,before_json,result_json,request_id FROM request_commands WHERE actor_id=NEW.actor_id AND request_id=NEW.request_id; END;
CREATE TRIGGER request_project_archive AFTER INSERT ON request_commands WHEN NEW.operation IN('project.archived','project.restored') BEGIN UPDATE request_commands SET workspace_id=(SELECT workspace_id FROM projects WHERE id=NEW.resource_id),before_json=(SELECT json_object('id',id,'workspaceId',workspace_id,'name',name,'status',status,'versioningMode',versioning_mode,'revision',revision,'createdAt',created_at) FROM projects WHERE id=NEW.resource_id) WHERE actor_id=NEW.actor_id AND request_id=NEW.request_id; UPDATE projects SET status=CASE WHEN NEW.operation='project.archived' THEN 'archived' ELSE archived_from_status END,archived_from_status=CASE WHEN NEW.operation='project.archived' THEN status ELSE NULL END,revision=revision+1 WHERE id=NEW.resource_id; UPDATE request_commands SET result_json=(SELECT json_object('id',id,'workspaceId',workspace_id,'name',name,'status',status,'versioningMode',versioning_mode,'revision',revision,'createdAt',created_at) FROM projects WHERE id=NEW.resource_id) WHERE actor_id=NEW.actor_id AND request_id=NEW.request_id; INSERT INTO audit_events(event_id,actor_type,actor_id,session_id,workspace_id,project_id,action,before_json,after_json,request_id) SELECT 'project:'||resource_id||':'||request_id,'user',actor_id,session_id,workspace_id,resource_id,operation,before_json,result_json,request_id FROM request_commands WHERE actor_id=NEW.actor_id AND request_id=NEW.request_id; END;
CREATE TRIGGER request_album_archive AFTER INSERT ON request_commands WHEN NEW.operation IN('album.archived','album.restored') BEGIN UPDATE request_commands SET workspace_id=(SELECT workspace_id FROM albums WHERE id=NEW.resource_id),before_json=(SELECT json_object('id',id,'workspaceId',workspace_id,'projectId',project_id,'name',name,'state',state,'isPinned',json(CASE WHEN is_pinned=1 THEN 'true' ELSE 'false' END),'legalHold',json(CASE WHEN legal_hold=1 THEN 'true' ELSE 'false' END),'revision',revision,'createdAt',created_at) FROM albums WHERE id=NEW.resource_id) WHERE actor_id=NEW.actor_id AND request_id=NEW.request_id; UPDATE albums SET state=CASE WHEN NEW.operation='album.archived' THEN 'archived' ELSE archived_from_state END,archived_from_state=CASE WHEN NEW.operation='album.archived' THEN state ELSE NULL END,revision=revision+1 WHERE id=NEW.resource_id; UPDATE request_commands SET result_json=(SELECT json_object('id',a.id,'workspaceId',a.workspace_id,'projectId',a.project_id,'name',a.name,'state',a.state,'isPinned',json(CASE WHEN a.is_pinned=1 THEN 'true' ELSE 'false' END),'legalHold',json(CASE WHEN a.legal_hold=1 THEN 'true' ELSE 'false' END),'revision',a.revision,'createdAt',a.created_at) FROM albums a WHERE a.id=NEW.resource_id) WHERE actor_id=NEW.actor_id AND request_id=NEW.request_id; INSERT INTO audit_events(event_id,actor_type,actor_id,session_id,workspace_id,project_id,album_id,action,before_json,after_json,request_id) SELECT 'album:'||resource_id||':'||request_id,'user',actor_id,session_id,workspace_id,(SELECT project_id FROM albums WHERE id=resource_id),resource_id,operation,before_json,result_json,request_id FROM request_commands WHERE actor_id=NEW.actor_id AND request_id=NEW.request_id; END;
CREATE TRIGGER request_command_no_delete BEFORE DELETE ON request_commands BEGIN SELECT RAISE(ABORT,'IMMUTABLE_COMMAND'); END;
CREATE TRIGGER request_command_no_update BEFORE UPDATE ON request_commands WHEN OLD.result_json IS NOT NULL OR NEW.actor_id<>OLD.actor_id OR NEW.request_id<>OLD.request_id OR NEW.operation<>OLD.operation OR NEW.payload_json<>OLD.payload_json OR NEW.session_id<>OLD.session_id OR NEW.resource_id<>OLD.resource_id OR (OLD.workspace_id IS NOT NULL AND NEW.workspace_id IS NOT OLD.workspace_id) OR (OLD.before_json IS NOT NULL AND NEW.before_json IS NOT OLD.before_json) BEGIN SELECT RAISE(ABORT,'IMMUTABLE_COMMAND'); END;
